import React from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
// Import Swiper styles
import 'swiper/css';
import './Header.css';

const Header = () => {
    return (
        <header className="site-header">
            <div className="header-container">
                <h1 className="site-title">Forum Name</h1>
                <nav className="main-nav">
                    <ul className="nav-list">
                        <li><a href="/">Home</a></li>
                        <li><a href="/forums">Forums</a></li>
                        <li><a href="/about">About</a></li>
                        <li><a href="/contact">Contact</a></li>
                    </ul>
                </nav>
            </div>
            <div className="slider-container">
                <Swiper
                    spaceBetween={50}
                    slidesPerView={1}
                    autoplay={{ delay: 3000 }}
                    loop={true}
                    pagination={{ clickable: true }}
                    navigation
                >
                    <SwiperSlide><div className="slide">New Feature: Dark Mode!</div></SwiperSlide>
                    <SwiperSlide><div className="slide">Check out the latest updates</div></SwiperSlide>
                    <SwiperSlide><div className="slide">Join our community events</div></SwiperSlide>
                </Swiper>
            </div>
        </header>
    );
};

export default Header;
